    /// W2-8:录制到**轮盘方向键**的按下/抬起驱动活轮盘(不是手势);
    /// 带虚拟层时同样内容展开成自包含的推离手势。
    #[test]
    fn macro_recorded_wheel_key_drives_live_wheel_or_gesture() {
        use crate::keymap::MacroStep;

        let m = mapper();
        let mut scheduled = Vec::new();
        // 默认配置自带标准轮盘(W/S/A/D),W = 上方向
        let live = Profile::default();
        let steps = vec![
            MacroStep {
                code: 17,
                pressed: true,
                delay_ms: 0,
            },
            MacroStep {
                code: 17,
                pressed: false,
                delay_ms: 200,
            },
        ];
        let start = Instant::now();
        schedule_macro(
            &MacroAction {
                virtual_profile: None,
                steps: steps.clone(),
                instructions: Vec::new(),

                repeat_while_held: false,
            },
            &live,
            &m,
            start,
            &mut scheduled,
            &mut MacroPlan::new(0),
        );
        let wheels: Vec<(Instant, bool, MacroWheelPart)> = scheduled
            .iter()
            .filter_map(|(t, a)| match a {
                SchedAct::MacroWheel { part, down, .. } => Some((*t, *down, *part)),
                _ => None,
            })
            .collect();
        assert_eq!(
            wheels,
            vec![
                (start, true, MacroWheelPart::Up),
                (
                    start + Duration::from_millis(200),
                    false,
                    MacroWheelPart::Up
                ),
            ],
            "活轮盘方向键:按下/抬起照录制时刻,驱动 MacWheel"
        );

        let mut scheduled = Vec::new();
        schedule_macro(
            &MacroAction {
                virtual_profile: Some(Box::new(live.clone())),
                steps,
                instructions: Vec::new(),

                repeat_while_held: false,
            },
            &live,
            &m,
            start,
            &mut scheduled,
            &mut MacroPlan::new(0),
        );
        assert!(
            !scheduled
                .iter()
                .any(|(_, a)| matches!(a, SchedAct::MacroWheel { .. })),
            "虚拟层的轮盘在设备上不存在,只能展开成手势"
        );
        let clicks: Vec<(Instant, bool, u64)> = scheduled
            .iter()
            .filter_map(|(t, a)| match a {
                SchedAct::MacroClick { pid, down, .. } => Some((*t, *down, *pid)),
                _ => None,
            })
            .collect();
        assert_eq!(clicks.len(), 2, "手势自包含:1 落指 + 1 抬起 {clicks:?}");
        assert_eq!(clicks[0], (start, true, clicks[0].2));
        assert_eq!(
            clicks[1],
            (start + Duration::from_millis(200), false, clicks[0].2)
        );
        assert!(
            scheduled
                .iter()
                .any(|(_, a)| matches!(a, SchedAct::MacroMove { .. })),
            "推离手势必须有中间轨迹"
        );
    }

    /// 2026-10-07(用户第 6 条):宏忠实于按键设置 —— 临时轮盘启用后,
    /// 有普通映射的方向键在宏里必须按"轮盘方向"生效(而不是原来的绑定);
    /// 启用键自己的绑定也永远不生效;停用后方向键落回绑定。
    #[test]
    fn macro_temp_wheel_enable_reassigns_direction_key() {
        use crate::keymap::{DEFAULT_RADIUS, MacroStep, TempWheel};

        let m = mapper();
        let mut profile = Profile::default();
        profile.wheels.clear();
        profile.wheels.push(Wheel {
            up: KeySet::single(17), // W
            down: KeySet::single(0),
            left: KeySet::single(0),
            right: KeySet::single(0),
            cx: 0.5,
            cy: 0.5,
            radius: 0.1,
            scope: 1.0,
            mode: WheelMode::Classic,
            kind: WheelKind::Standard,
            directions: Vec::new(),
            center_radius: 0.1,
            execute_duration_ms: 180,
            temp: Some(TempWheel {
                key: KeySet::single(90), // Z:临时轮盘启用键(按住型)
                mode: TempMode::Hold,
            }),
        });
        // 方向键与启用键在配置里都有普通映射 —— 启用后都不该走绑定
        for key in [17u16, 90] {
            profile.binds.push(KeyBind {
                key,
                action: Action::Tap {
                    x: 0.9,
                    y: 0.9,
                    duration_ms: 40,
                    radius: DEFAULT_RADIUS,
                    repeat_interval_ms: 0,
                },
                fps_only: false,
                tail_delay_ms: 0,
            });
        }
        let steps = vec![
            MacroStep {
                code: 90,
                pressed: true,
                delay_ms: 0,
            }, // t=0 启用
            MacroStep {
                code: 17,
                pressed: true,
                delay_ms: 50,
            }, // t=50 W:走轮盘,不走绑定
            MacroStep {
                code: 17,
                pressed: false,
                delay_ms: 60,
            }, // t=110
            MacroStep {
                code: 90,
                pressed: false,
                delay_ms: 60,
            }, // t=170 停用
            MacroStep {
                code: 17,
                pressed: true,
                delay_ms: 10,
            }, // t=180 W:恢复绑定
            MacroStep {
                code: 17,
                pressed: false,
                delay_ms: 10,
            }, // t=190
        ];
        let start = Instant::now();
        let mut scheduled = Vec::new();
        schedule_macro(
            &MacroAction {
                virtual_profile: None,
                steps,
                instructions: Vec::new(),

                repeat_while_held: false,
            },
            &profile,
            &m,
            start,
            &mut scheduled,
            &mut MacroPlan::new(0),
        );
        let clicks: Vec<(Instant, bool, u64)> = scheduled
            .iter()
            .filter_map(|(t, a)| match a {
                SchedAct::MacroClick { pid, down, .. } => Some((*t, *down, *pid)),
                _ => None,
            })
            .collect();
        assert_eq!(
            clicks.len(),
            2,
            "启用期间方向键不得走绑定、启用键的绑定也要被吞: {clicks:?}"
        );
        assert_eq!(clicks[0].0, start + Duration::from_millis(180));
        assert!(clicks[0].1, "停用后 W 落回绑定(按下)");
        assert_eq!(clicks[1].0, start + Duration::from_millis(190));
        assert_eq!(clicks[0].2, clicks[1].2);
        let wheels: Vec<(Instant, bool, MacroWheelPart)> = scheduled
            .iter()
            .filter_map(|(t, a)| match a {
                SchedAct::MacroWheel { part, down, .. } => Some((*t, *down, *part)),
                _ => None,
            })
            .collect();
        assert_eq!(
            wheels,
            vec![
                (start + Duration::from_millis(50), true, MacroWheelPart::Up),
                (
                    start + Duration::from_millis(110),
                    false,
                    MacroWheelPart::Up
                ),
            ],
            "启用后 W = 上方向,按录制时刻按下/抬起"
        );
    }

    /// R1(2026-10-08),宏回放一侧:**临时摇杆 > 永久摇杆**,以及停用时**当场交还**。
    ///
    /// 规则与引擎路径相同,但宏的状态是"排出来的"、不是每帧从物理键推出来的,
    /// 所以停用那一刻必须显式补上那一推(见 `macro_wheel_transition` 的 heir 分支)。
    /// 场景:永久轮盘 `up` = W(17);临时轮盘(按住型,启用键 Z=90)`up` 也是 W。
    ///   ① 启用后按 W:只有临时摇杆推(不许两把一起推,也**不许**落回普通绑定);
    ///   ② 松开启用键时 W 还按着:临时摇杆抬指,永久轮盘当场接手;
    ///   ③ 松开 W:永久轮盘抬指。
    /// W 上特意挂了长按绑定当探针 —— 全程一次都不该出现。
    #[test]
    fn macro_temp_wheel_takes_over_and_hands_back_the_shared_key() {
        use crate::keymap::{DEFAULT_RADIUS, MacroStep, TempWheel};

        let m = mapper();
        let wheel = |temp: Option<TempWheel>| Wheel {
            up: KeySet::single(17), // W:永久轮盘与临时轮盘撞在同一根键上
            down: KeySet::single(0),
            left: KeySet::single(0),
            right: KeySet::single(0),
            cx: 0.5,
            cy: 0.5,
            radius: 0.1,
            scope: 1.0,
            mode: WheelMode::Classic,
            kind: WheelKind::Standard,
            directions: Vec::new(),
            center_radius: 0.1,
            execute_duration_ms: 180,
            temp,
        };
        let mut profile = Profile::default();
        profile.wheels.clear();
        profile.wheels.push(wheel(None));
        profile.wheels.push(wheel(Some(TempWheel {
            key: KeySet::single(90), // Z
            mode: TempMode::Hold,
        })));
        profile.binds.clear();
        profile.binds.push(KeyBind {
            key: 17,
            action: Action::Hold {
                x: 0.9,
                y: 0.9,
                radius: DEFAULT_RADIUS,
            },
            fps_only: false,
            tail_delay_ms: 0,
        });
        let steps = vec![
            MacroStep {
                code: 90,
                pressed: true,
                delay_ms: 0,
            }, // t=0 启用临时摇杆
            MacroStep {
                code: 17,
                pressed: true,
                delay_ms: 50,
            }, // t=50 W
            MacroStep {
                code: 90,
                pressed: false,
                delay_ms: 60,
            }, // t=110 停用(W 还按着)
            MacroStep {
                code: 17,
                pressed: false,
                delay_ms: 60,
            }, // t=170
        ];
        let start = Instant::now();
        let mut scheduled = Vec::new();
        schedule_macro(
            &MacroAction {
                virtual_profile: None,
                steps,
                instructions: Vec::new(),

                repeat_while_held: false,
            },
            &profile,
            &m,
            start,
            &mut scheduled,
            &mut MacroPlan::new(0),
        );

        let at = |ms: u64| start + Duration::from_millis(ms);
        let wheels: Vec<(Instant, usize, bool, MacroWheelPart)> = scheduled
            .iter()
            .filter_map(|(t, a)| match a {
                SchedAct::MacroWheel { wheel, part, down } => Some((*t, *wheel, *down, *part)),
                _ => None,
            })
            .collect();
        assert_eq!(
            wheels,
            vec![
                (at(50), 1, true, MacroWheelPart::Up), // 启用期间:只有临时摇杆推
                (at(110), 1, false, MacroWheelPart::Up), // 停用:临时摇杆抬指
                (at(110), 0, true, MacroWheelPart::Up), // 停用:永久轮盘当场接手
                (at(170), 0, false, MacroWheelPart::Up), // 松 W
            ],
            "临时摇杆启用时独占 W,停用后当场交还给永久轮盘"
        );
        let clicks = scheduled
            .iter()
            .filter(|(_, a)| matches!(a, SchedAct::MacroClick { .. }))
            .count();
        assert_eq!(clicks, 0, "W 全程归摇杆,一次都不许落回普通绑定");
    }

    /// R1 的**启用侧**:方向键**已经被永久轮盘按着**,之后才启用临时轮盘。
    ///
    /// 与上一例(先按启用键、后按方向键)是一条规则的两个方向,但走的是不同的
    /// 代码路径:上一例靠 `emit_step_press` 的 `temp_taken` 把永久轮盘挡在门外;
    /// 这一例永久轮盘的部件**已经在 `pending` 里了**,只能靠 `macro_wheel_transition`
    /// 的启用分支把它当场抬掉 —— 少了这一抬,两把轮盘会同时把触点推到设备上。
    #[test]
    fn macro_temp_wheel_enable_evicts_the_permanent_wheel_already_on_that_key() {
        use crate::keymap::{DEFAULT_RADIUS, MacroStep, TempWheel};

        let m = mapper();
        let wheel = |temp: Option<TempWheel>| Wheel {
            up: KeySet::single(17), // W:永久轮盘与临时轮盘撞在同一根键上
            down: KeySet::single(0),
            left: KeySet::single(0),
            right: KeySet::single(0),
            cx: 0.5,
            cy: 0.5,
            radius: 0.1,
            scope: 1.0,
            mode: WheelMode::Classic,
            kind: WheelKind::Standard,
            directions: Vec::new(),
            center_radius: 0.1,
            execute_duration_ms: 180,
            temp,
        };
        let mut profile = Profile::default();
        profile.wheels.clear();
        profile.wheels.push(wheel(None));
        profile.wheels.push(wheel(Some(TempWheel {
            key: KeySet::single(90), // Z
            mode: TempMode::Hold,
        })));
        profile.binds.clear();
        profile.binds.push(KeyBind {
            key: 17,
            action: Action::Hold {
                x: 0.9,
                y: 0.9,
                radius: DEFAULT_RADIUS,
            },
            fps_only: false,
            tail_delay_ms: 0,
        });
        let steps = vec![
            MacroStep {
                code: 17,
                pressed: true,
                delay_ms: 0,
            }, // t=0 W 先按着 —— 此刻吃它的是永久轮盘
            MacroStep {
                code: 90,
                pressed: true,
                delay_ms: 50,
            }, // t=50 这时才启用临时摇杆
            MacroStep {
                code: 90,
                pressed: false,
                delay_ms: 60,
            }, // t=110 停用
            MacroStep {
                code: 17,
                pressed: false,
                delay_ms: 60,
            }, // t=170
        ];
        let start = Instant::now();
        let mut scheduled = Vec::new();
        schedule_macro(
            &MacroAction {
                virtual_profile: None,
                steps,
                instructions: Vec::new(),

                repeat_while_held: false,
            },
            &profile,
            &m,
            start,
            &mut scheduled,
            &mut MacroPlan::new(0),
        );

        let at = |ms: u64| start + Duration::from_millis(ms);
        let wheels: Vec<(Instant, usize, bool, MacroWheelPart)> = scheduled
            .iter()
            .filter_map(|(t, a)| match a {
                SchedAct::MacroWheel { wheel, part, down } => Some((*t, *wheel, *down, *part)),
                _ => None,
            })
            .collect();
        assert_eq!(
            wheels,
            vec![
                (at(0), 0, true, MacroWheelPart::Up), // 临时摇杆还没启用:永久轮盘先推着
                (at(50), 0, false, MacroWheelPart::Up), // 启用:永久轮盘当场让位(先抬)
                (at(50), 1, true, MacroWheelPart::Up), // 启用:临时摇杆接手(后按)
                (at(110), 1, false, MacroWheelPart::Up), // 停用:临时摇杆抬指
                (at(110), 0, true, MacroWheelPart::Up), // 停用:永久轮盘当场交还
                (at(170), 0, false, MacroWheelPart::Up), // 松 W
            ],
            "临时摇杆启用瞬间必须把已经按着的永久轮盘抬掉,不能两把同时推"
        );
        // 同一时刻必须是"先抬永久、后按临时",否则设备上会短暂出现双触点。
        let idx = |i: usize| {
            scheduled
                .iter()
                .position(|(t, a)| {
                    *t == at(50)
                        && matches!(a, SchedAct::MacroWheel { wheel, down, .. } if *wheel == i && *down == (i == 1))
                })
                .expect("t=50 的两条 MacroWheel 都应在")
        };
        assert!(
            idx(0) < idx(1),
            "同刻的顺序必须是先抬永久轮盘、再按临时轮盘"
        );
        let clicks = scheduled
            .iter()
            .filter(|(_, a)| matches!(a, SchedAct::MacroClick { .. }))
            .count();
        assert_eq!(clicks, 0, "W 全程归摇杆,一次都不许落回普通绑定");
    }

    /// 切换型临时轮盘:每次**按下**翻转,抬起不翻转 —— 宏里同样成立。
